export function SyntheticMessage(aHeaders, aBodyPart, aMetaState) {
  // we currently do not need to call SyntheticPart's constructor...
  this.headers = aHeaders || {};
  this.bodyPart = aBodyPart || new SyntheticPartLeaf("");
  this.metaState = aMetaState || {};
  for (const key in _DEFAULT_META_STATES) {
    const value = _DEFAULT_META_STATES[key];
    if (!(key in this.metaState)) {
      this.metaState[key] = value;
    }
  }
}

SyntheticMessage.prototype = {
  __proto__: SyntheticPart.prototype,
  _contentType: "message/rfc822",
  _charset: null,
  _format: null,
  _encoding: null,

  /**
   * Copy this message's data to create a new message.
   *
   * As implemented, this will return a new message with independent headers and
   * metastate, but the body object will still be shared between original and
   * new objects.
   *
   * @returns {SyntheticMessage}
   */
  clone() {
    return new SyntheticMessage(
      structuredClone(this.headers),
      this.bodyPart,
      structuredClone(this.metaState)
    );
